            <View style={styles.quranPill}>
              <BookOpen size={13} color={colors.ink} />
              <Text style={styles.quranPillText}>HOLY QURAN AUDIO</Text>
            </View>
            <CassetteTag label="RECITATIONS" bg={colors.ink} textColor={colors.mint} />
