              placeholder="Search surah or reciter..."
              placeholderTextColor={colors.grayText}
              value={searchQuery}
              onChangeText={setSearchQuery}
            />
          </View>
        </View>
      </View>

      {/* Reciters Horizontal Carousel */}
      <View style={styles.recitersSection}>
