                onPress={() => setSelectedReciter(active ? null : r.name)}
              >
                <Text
                  style={[
                    styles.reciterPillText,
                    active && styles.reciterPillTextActive,
                  ]}
                >
                  {r.name} ({r.count})
                </Text>
              </TouchableOpacity>
            );
          })}
        </ScrollView>
      </View>

