                      {reciter.name}
                    </Text>
                    <View style={styles.reciterCardBadge}>
                      <Text style={styles.reciterCardBadgeText}>
                        {reciter.count} Surahs
                      </Text>
                    </View>
                  </View>
                </TouchableOpacity>
              ))}
            </View>
          </View>
        ) : (
